{"command":"python3 - << 'EOF'
import os, sys, json, re, hashlib, glob

def get_sha256(filepath):
    h = hashlib.sha256()
    try:
        with open(filepath, 'rb') as f:
            while chunk := f.read(8192):
                h.update(chunk)
        return h.hexdigest()
    except Exception:
        return ""

bases = []
if os.path.exists('/app_target'):
    bases.append('/app_target')
bases.append('')

artifacts = []
cron_files = set()
for base in bases:
    patterns = [
        f"{base}/etc/cron.d/*",
        f"{base}/etc/crontab",
        f"{base}/etc/cron.daily/*",
        f"{base}/etc/cron.hourly/*",
        f"{base}/etc/cron.weekly/*",
        f"{base}/etc/cron.monthly/*",
        f"{base}/var/spool/cron/*",
        f"{base}/var/spool/cron/crontabs/*",
    ]
    for p in patterns:
        for f in glob.glob(p):
            if os.path.isfile(f):
                real_path = os.path.realpath(f)
                cron_files.add(real_path)

std_prefixes = ('/usr/bin/', '/bin/', '/sbin/', '/usr/sbin/', '/usr/libexec/', '/usr/lib/', '/usr/lib64/')
suspicious_kw = ['/tmp', '/var/tmp', '/dev/shm', '/run/lock', 'curl ', 'wget ', 'fetch ', 'nc ', 'netcat ', 'ncat ', 'socat ', 'base64', 'eval ', '/dev/tcp', '/dev/udp', '| bash', '| sh', '|/bin/bash', '|/bin/sh']

for real_path in sorted(cron_files):
    try:
        with open(real_path, 'r', encoding='utf-8', errors='replace') as fp:
            lines = fp.readlines()
    except Exception:
        continue

    file_sha256 = get_sha256(real_path)

    for idx, line in enumerate(lines, 1):
        sline = line.strip()
        if not sline or sline.startswith('#'):
            continue
        if sline.startswith(('SHELL=', 'PATH=', 'MAILTO=', 'HOME=', 'RANDOM=')):
            continue

        is_suspicious = False
        for kw in suspicious_kw:
            if kw in sline:
                is_suspicious = True
                break

        if not is_suspicious:
            tokens = sline.split()
            if len(tokens) >= 6:
                for tok in tokens[5:]:
                    if tok.startswith('/') and not any(tok.startswith(pref) for pref in std_prefixes):
                        is_suspicious = True
                        break

        if is_suspicious:
            user = None
            if '/var/spool/cron/' in real_path:
                user = os.path.basename(real_path)
            else:
                tokens = sline.split()
                if len(tokens) >= 6:
                    possible_user = tokens[5]
                    if re.match(r'^[a-zA-Z0-9_-]+$', possible_user) and not possible_user.startswith('/'):
                        user = possible_user

            artifacts.append({
                "type": "cron_job",
                "path": real_path,
                "sha256": file_sha256,
                "details": {
                    "line_number": idx,
                    "content_preview": sline[:100],
                    "user": user
                }
            })

print(json.dumps(artifacts, indent=2))
EOF"}

