{"command":"python3 - << 'EOF'
import os, glob, subprocess

def is_dpkg_managed(path):
    # Try both exact path and /lib/systemd/system/<base>
    for p in [path, f"/lib/systemd/system/{os.path.basename(path)}", f"/usr/lib/systemd/system/{os.path.basename(path)}"]:
        try:
            res = subprocess.run(['dpkg', '-S', p], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
            if res.returncode == 0:
                return True
        except Exception:
            pass
    return False

bases = ['/app_target', '']
unit_files = set()

for base in bases:
    for dirpath in [f"{base}/etc/systemd/system", f"{base}/usr/lib/systemd/system", f"{base}/run/systemd/system", f"{base}/lib/systemd/system"]:
        if os.path.exists(dirpath):
            for root, dirs, files in os.walk(dirpath):
                for file in files:
                    full = os.path.join(root, file)
                    real = os.path.realpath(full)
                    if os.path.isfile(real):
                        unit_files.add(real)

suspicious_kw = ['/tmp', '/var/tmp', '/dev/shm', ' nc ', ' nc\t', ' netcat ', ' ncat ', ' socat ', 'python', 'eval ', '/dev/tcp', '/dev/udp', 'while true', 'attacker', 'backdoor', '/app_target/', 'hidden_backdoor']

flagged = []
for real in sorted(unit_files):
    fname = os.path.basename(real)
    is_hidden = fname.startswith('.')
    pkg = is_dpkg_managed(real)

    exec_line = None
    has_susp_cmd = False
    try:
        with open(real, 'r', encoding='utf-8', errors='replace') as fp:
            for line in fp:
                sline = line.strip()
                if sline.startswith(('ExecStart', 'ExecStartPre', 'ExecStartPost', 'ExecReload')):
                    if exec_line is None:
                        exec_line = sline
                    for kw in suspicious_kw:
                        if kw in sline:
                            has_susp_cmd = True
                            break
    except Exception:
        continue

    # Decision logic:
    # 1) If hidden file -> flagged
    # 2) If not in dpkg and (has_susp_cmd or not pkg)
    # Wait, in /etc/systemd/system/ persistence.service is not in dpkg and has_susp_cmd
    # /app_target/etc/systemd/system/app_backdoor.service is not in dpkg and has_susp_cmd
    # /usr/lib/systemd/system/.hidden_service.service is hidden
    if is_hidden or (not pkg and (has_susp_cmd or '/etc/systemd/system/' in real or '/app_target/' in real)):
        if is_hidden or has_susp_cmd or not pkg:
            flagged.append((real, exec_line, is_hidden, pkg, has_susp_cmd))

for r, e, h, p, c in flagged:
    print(f"Flagged: {r}\n  Exec: {e}\n  hidden={h}, pkg={p}, susp_cmd={c}\n")
EOF"}

