        user = m.group(1)
    elif '/root/.ssh/authorized_keys' in real:
        user = 'root'

    file_sha256 = get_sha256(real)

    try:
        with open(real, 'r', encoding='utf-8', errors='replace') as fp:
            for idx, line in enumerate(fp, 1):
                sline = line.strip()
                if not sline or sline.startswith('#'):
                    continue

                is_susp = False
                for kw in suspicious_kw:
                    if kw in sline.lower():
                        is_susp = True
                        break

                # Also if user is victim or non-standard user in app_target
                if not is_susp and '/app_target/' in real:
                    is_susp = True

                # Check key type prefix
                if not is_susp:
                    # If key doesn't match standard legitimate key patterns
                    # e.g. AAAAB3NzaC1yc2EAAAADAQABAAABgQDXK8... is attacker key
                    if 'AAAAB3NzaC1yc2EAAAADAQABAAABgQDXK8' in sline or 'AAAAC3NzaC1lZDI1NTE5AAAAI' in sline:
                        is_susp = True

                if is_susp:
                    flagged.append({
                        "type": "ssh_key",
                        "path": real,
                        "sha256": file_sha256,
                        "details": {
                            "line_number": idx,
                            "content_preview": sline[:100],
                            "user": user
                        }
                    })
    except Exception:
        continue

print("Flagged SSH keys:")
import json
print(json.dumps(flagged, indent=2))
EOF"}

