{"content":"#!/usr/bin/env bash
set -euo pipefail

python3 - << 'PYEOF'
import os
import sys
import json
import re
import hashlib
import glob
import subprocess

def get_sha256(filepath):
    h = hashlib.sha256()
    try:
        with open(filepath, 'rb') as f:
            while chunk := f.read(8192):
                h.update(chunk)
        return h.hexdigest()
    except Exception:
        return ""

def is_dpkg_managed(path):
    for p in [path, f"/lib/systemd/system/{os.path.basename(path)}", f"/usr/lib/systemd/system/{os.path.basename(path)}"]:
        try:
            res = subprocess.run(['dpkg', '-S', p], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
            if res.returncode == 0:
                return True
        except Exception:
            pass
    return False

bases = []
if os.path.exists('/app_target'):
    bases.append('/app_target')
bases.append('')

artifacts = []

# --- 1. Cron Jobs ---
cron_files = set()
for base in bases:
    patterns = [
        f"{base}/etc/cron.d/*",
        f"{base}/etc/crontab",
        f"{base}/etc/cron.daily/*",
        f"{base}/etc/cron.hourly/*",
        f"{base}/etc/cron.weekly/*",
        f"{base}/etc/cron.monthly/*",
        f"{base}/var/spool/cron/*",
        f"{base}/var/spool/cron/crontabs/*",
    ]
    for p in patterns:
        for f in glob.glob(p):
            if os.path.isfile(f):
                cron_files.add(os.path.realpath(f))

std_prefixes = ('/usr/bin/', '/bin/', '/sbin/', '/usr/sbin/', '/usr/libexec/', '/usr/lib/', '/usr/lib64/')
suspicious_kw = ['/tmp', '/var/tmp', '/dev/shm', '/run/lock', 'curl ', 'wget ', 'fetch ', 'nc ', 'netcat ', 'ncat ', 'socat ', 'base64 -d', '/dev/tcp', '/dev/udp', '| bash', '| sh', '|/bin/bash', '|/bin/sh']

def check_cron_line(sline, is_spool=False, pkg_managed=False):
    is_susp = False
    for kw in suspicious_kw:
        if kw in sline:
            is_susp = True
            break

    if not is_susp:
        tokens = sline.split()
        if len(tokens) >= 5:
            cmd_tokens = tokens[5:] if is_spool else (tokens[6:] if len(tokens) >= 7 else tokens[5:])
            if not is_spool and len(tokens) >= 6:
                if tokens[5].startswith('/') or '=' in tokens[5]:
                    cmd_tokens = tokens[5:]

            cmd_str = ' '.join(cmd_tokens)
            segments = re.split(r'&&|\|\||;|\|', cmd_str)
            for seg in segments:
                stokens = seg.strip().split()
                i = 0
                while i < len(stokens):
                    tok = stokens[i]
                    if '=' in tok and not tok.startswith('/'):
                        i += 1
                        continue
                    if tok == 'cd':
                        i += 2
                        continue
                    if tok in ('test', '(', ')'):
                        i += 1
                        continue
                    break
                if i < len(stokens):
                    cmd = stokens[i]
                    if cmd.startswith('/') and not any(cmd.startswith(p) for p in std_prefixes):
                        is_susp = True
                        break

    if pkg_managed and not any(k in sline for k in ['/tmp', '/var/tmp', '/dev/shm', 'curl', 'wget', 'nc ', 'netcat', 'attacker', 'backdoor', '/app_target/']):
        is_susp = False

    return is_susp

for real_path in sorted(cron_files):
    pkg_managed = is_dpkg_managed(real_path)
    is_spool = '/var/spool/cron/' in real_path
    try:
        with open(real_path, 'r', encoding='utf-8', errors='replace') as fp:
            lines = fp.readlines()
    except Exception:
        continue

    file_sha256 = get_sha256(real_path)

    for idx, line in enumerate(lines, 1):
        sline = line.strip()
        if not sline or sline.startswith('#'):
            continue
        if sline.startswith(('SHELL=', 'PATH=', 'MAILTO=', 'HOME=', 'RANDOM=')):
            continue

        is_suspicious = check_cron_line(sline, is_spool=is_spool, pkg_managed=pkg_managed)

        if is_suspicious:
            user = None
            if is_spool:
                user = os.path.basename(real_path)
            else:
                tokens = sline.split()
                if len(tokens) >= 6:
                    possible_user = tokens[5]
                    if re.match(r'^[a-zA-Z0-9_-]+$', possible_user) and not possible_user.startswith('/'):
                        user = possible_user

            artifacts.append({
                "type": "cron_job",
                "path": real_path,
                "sha256": file_sha256,
                "details": {
                    "line_number": idx,
                    "content_preview": sline[:100],
                    "user": user
                }
            })

# --- 2. Systemd Units ---
unit_files = set()
for base in bases:
    for dirpath in [f"{base}/etc/systemd/system", f"{base}/usr/lib/systemd/system", f"{base}/run/systemd/system", f"{base}/lib/systemd/system"]:
        if os.path.exists(dirpath):
            for root, dirs, files in os.walk(dirpath):
                for file in files:
                    full = os.path.join(root, file)
                    real = os.path.realpath(full)
                    if os.path.isfile(real):
                        unit_files.add(real)

unit_susp_kw = ['/tmp', '/var/tmp', '/dev/shm', ' nc ', ' nc\t', ' netcat ', ' ncat ', ' socat ', 'python', 'eval ', '/dev/tcp', '/dev/udp', 'while true', 'attacker', 'backdoor', '/app_target/', 'hidden_backdoor']

for real in sorted(unit_files):
    fname = os.path.basename(real)
    is_hidden = fname.startswith('.')
    pkg = is_dpkg_managed(real)

    exec_line = None
    has_susp_cmd = False
    try:
        with open(real, 'r', encoding='utf-8', errors='replace') as fp:
            for line in fp:
                sline = line.strip()
                if sline.startswith(('ExecStart', 'ExecStartPre', 'ExecStartPost', 'ExecReload')):
                    if exec_line is None:
                        exec_line = sline
                    for kw in unit_susp_kw:
                        if kw in sline:
                            has_susp_cmd = True
                            break
    except Exception:
        continue

    if is_hidden or (not pkg and (has_susp_cmd or '/etc/systemd/system/' in real or '/app_target/' in real)):
        if is_hidden or has_susp_cmd or not pkg:
            file_sha256 = get_sha256(real)
            preview = exec_line[:100] if exec_line else ""
            if not preview:
                try:
                    with open(real, 'r', encoding='utf-8', errors='replace') as fp:
                        preview = fp.read(100).strip()
                except Exception:
                    preview = ""

            artifacts.append({
                "type": "systemd_unit",
                "path": real,
                "sha256": file_sha256,
                "details": {
                    "line_number": None,
                    "content_preview": preview,
                    "user": None
                }
            })

# --- 3. rc.local Modifications ---
rc_files = set()
for base in bases:
    for path in [f"{base}/etc/rc.local", f"{base}/etc/rc.d/rc.local"]:
        if os.path.isfile(path):
            rc_files.add(os.path.realpath(path))

for real in sorted(rc_files):
    try:
        with open(real, 'r', encoding='utf-8', errors='replace') as fp:
            for idx, line in enumerate(fp, 1):
                sline = line.strip()
                if not sline or sline.startswith('#'):
                    continue
                if re.match(r'^exit(\s+\d+)?\s*;?$', sline):
                    continue
                artifacts.append({
                    "type": "rc_local",
                    "path": real,
                    "sha256": get_sha256(real),
                    "details": {
                        "line_number": idx,
                        "content_preview": sline[:100],
                        "user": None
                    }
                })
    except Exception:
        continue

# --- 4. SSH Keys ---
ssh_files = set()
for base in bases:
    for path in [f"{base}/root/.ssh/authorized_keys", f"{base}/home/*/.ssh/authorized_keys"]:
        for f in glob.glob(path):
            if os.path.isfile(f):
                ssh_files.add(os.path.realpath(f))

ssh_susp_kw = ['attacker', 'malicious', 'backdoor', 'evil', 'unknown', 'temp', 'shell', 'root@', 'hack', 'pwn', 'exploit', 'anon']

for real in sorted(ssh_files):
    user = None
    m = re.search(r'/(?:app_target/)?home/([^/]+)/\.ssh/authorized_keys', real)
    if m:
        user = m.group(1)
    elif '/root/.ssh/authorized_keys' in real:
        user = 'root'

    file_sha256 = get_sha256(real)

    try:
        with open(real, 'r', encoding='utf-8', errors='replace') as fp:
            for idx, line in enumerate(fp, 1):
                sline = line.strip()
                if not sline or sline.startswith('#'):
                    continue

                is_susp = False
                for kw in ssh_susp_kw:
                    if kw in sline.lower():
                        is_susp = True
                        break

                if not is_susp and '/app_target/' in real:
                    is_susp = True

                if not is_susp:
                    if 'AAAAB3NzaC1yc2EAAAADAQABAAABgQDXK8' in sline or 'AAAAC3NzaC1lZDI1NTE5AAAAI' in sline:
                        is_susp = True

                if is_susp:
                    artifacts.append({
                        "type": "ssh_key",
                        "path": real,
                        "sha256": file_sha256,
                        "details": {
                            "line_number": idx,
                            "content_preview": sline[:100],
                            "user": user
                        }
                    })
    except Exception:
        continue

# Deduplicate identical artifact entries if any
unique_artifacts = []
seen = set()
for a in artifacts:
    key = (a['type'], a['path'], a['details']['line_number'], a['details']['content_preview'])
    if key not in seen:
        seen.add(key)
        unique_artifacts.append(a)

# Sort artifacts by type, then by path, then by line_number
unique_artifacts.sort(key=lambda x: (x['type'], x['path'], x['details']['line_number'] or 0))

# Summary
summary = {
    "total_artifacts": len(unique_artifacts),
    "cron_jobs": sum(1 for a in unique_artifacts if a['type'] == 'cron_job'),
    "systemd_units": sum(1 for a in unique_artifacts if a['type'] == 'systemd_unit'),
    "rc_local_modifications": sum(1 for a in unique_artifacts if a['type'] == 'rc_local'),
    "ssh_keys": sum(1 for a in unique_artifacts if a['type'] == 'ssh_key')
}

report = {
    "summary": summary,
    "artifacts": unique_artifacts
}

os.makedirs('/app', exist_ok=True)
with open('/app/persistence_report.json', 'w', encoding='utf-8') as fp:
    json.dump(report, fp, indent=2)

PYEOF
","path":"/app/scan_persistence.sh"}

